import "aos/dist/aos.css";
import AppContext from "../../../../Context";
import { useContext } from "react";
import { IPVS1Brand, IPVS1DocAcc, IPVS1DocRej, IPVS1Opp } from "../../../asset/image";

export default function SuccessDefended() {
    const { language } = useContext(AppContext);

    const trademarkDefenseCases = [
        {
            status:
                language === "id"
                    ? "SANGGAHAN DITERIMA"
                    : "OPPOSITION ACCEPTED",

            title:
                language === "id"
                    ? "Merek yang Berhasil Kami Pertahankan"
                    : "Trademarks We've Successfully Defended",

            ourBrand: {
                logo: IPVS1Brand,
                name: "ASTON & Lukisan ( JID2023013480 )",
                ownerLabel: language === "id" ? "Pemilik" : "Owner",
                owner: "DEWI AYU CANCERINA",
            },

            opponentBrand: {
                logo: IPVS1Opp,
                name: "ASTON ( IDM000411303 )",
                ownerLabel: language === "id" ? "Pemilik" : "Owner",
                owner: "AHMAD AGUS PURNAWAN"
            },

            documents: {
                oppositionTitle:
                    language === "id"
                        ? "Surat Penolakan"
                        : "Opposition Letter",

                acceptanceTitle:
                    language === "id"
                        ? "Surat Penerimaan"
                        : "Acceptance Letter",

                oppositionImage: IPVS1DocRej,
                acceptanceImage: IPVS1DocAcc,
            },

            summaryTitle:
                language === "id"
                    ? "Ringkasan Kasus"
                    : "Case Summary",

            summary:
                language === "id"
                    ? "Merek berhasil dipertahankan setelah tim kami menyampaikan argumentasi hukum dan bukti yang menunjukkan adanya perbedaan visual, konseptual, serta keseluruhan kesan yang signifikan antara kedua merek, sehingga sanggahan diterima."
                    : "The trademark was successfully defended after our team presented legal arguments and evidence demonstrating significant visual, conceptual, and overall commercial impression differences between the two marks, resulting in the opposition being accepted.",
        },
    ];

    return (
        <div className="pt-24">

            {/* HERO STYLE SECTION */}
            <section className="mb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">
                    <div className="mb-14">
                        {/* Heading */}
                        <div className="text-center mb-10">
                            <h2 className="text-3xl font-bold text-primary-black-500 mt-4">
                                {language === "id"
                                    ? "Merek yang Berhasil Kami Pertahankan"
                                    : "Trademarks We've Successfully Defended"}
                            </h2>
                        </div>

                        {trademarkDefenseCases.map((item, index) => (
                            <div
                                key={index}
                                data-aos="fade-up"
                                data-aos-delay={index * 100}
                                className="rounded-3xl shadow-xl overflow-hidden border border-slate-200 bg-white mb-14"
                            >
                                {/* Status */}
                                <div className="bg-emerald-600 text-white text-center py-4">
                                    <span className="font-bold tracking-wide text-lg">
                                        {language === "id" ? "STATUS : " : "STATUS : "}
                                        {item.status}
                                    </span>
                                </div>

                                {/* Brand Comparison */}
                                <div className="grid grid-cols-1 md:grid-cols-2">
                                    {/* Our Brand */}
                                    <div className="relative p-8 border-b md:border-b-0 md:border-r border-slate-200">
                                        {/* Badge */}
                                        <div className="absolute top-4 left-4 bg-emerald-100 text-emerald-700 text-xs font-bold px-3 py-1 rounded-full">
                                            {language === "id" ? "Merek Klien Kami" : "Our Client's Brand"}
                                        </div>

                                        <div className="flex justify-center">
                                            <div className="w-28 h-28 rounded-full flex items-center justify-center">
                                                <img
                                                    src={item.ourBrand.logo}
                                                    alt={item.ourBrand.name}
                                                    className="max-h-20 object-contain"
                                                />
                                            </div>
                                        </div>

                                        <div className="mt-6 space-y-2 text-center">
                                            <h3 className="font-bold text-xl text-primary-black-500">
                                                {item.ourBrand.name}
                                            </h3>

                                            <p className="text-gray-600">
                                                <span className="font-semibold">
                                                    {item.ourBrand.ownerLabel} :
                                                </span>{" "}
                                                {item.ourBrand.owner}
                                            </p>
                                        </div>
                                    </div>

                                    {/* Opponent */}
                                    <div className="relative p-8">
                                        {/* Badge */}
                                        <div className="absolute top-4 left-4 bg-red-100 text-red-700 text-xs font-bold px-3 py-1 rounded-full">
                                            {language === "id" ? "Merek Oposisi" : "Opponent"}
                                        </div>

                                        <div className="flex justify-center">
                                            <div className="w-28 h-28 rounded-full flex items-center justify-center">
                                                <img
                                                    src={item.opponentBrand.logo}
                                                    alt={item.opponentBrand.name}
                                                    className="max-h-20 object-contain"
                                                />
                                            </div>
                                        </div>

                                        <div className="mt-6 space-y-2 text-center">
                                            <h3 className="font-bold text-xl text-primary-black-500">
                                                {item.opponentBrand.name}
                                            </h3>

                                            <p className="text-gray-600">
                                                <span className="font-semibold">
                                                    {item.opponentBrand.ownerLabel} :
                                                </span>{" "}
                                                {item.opponentBrand.owner}
                                            </p>
                                        </div>
                                    </div>
                                </div>

                                {/* Documents */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 p-8 bg-slate-50">
                                    <div>
                                        <h4 className="font-semibold mb-3 text-center text-red-600">
                                            {item.documents.oppositionTitle}
                                        </h4>

                                        <div className="rounded-xl overflow-hidden shadow-md border border-slate-200">
                                            <div className="w-full max-h-[600px] aspect-video bg-white flex items-center justify-center ">
                                                <img
                                                    src={item.documents.oppositionImage}
                                                    alt={item.documents.oppositionTitle}
                                                    className="w-full h-full object-contain hover:scale-105 transition duration-500 my-3"
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    <div>
                                        <h4 className="font-semibold mb-3 text-center text-emerald-600">
                                            {item.documents.acceptanceTitle}
                                        </h4>

                                        <div className="rounded-xl overflow-hidden shadow-md border border-slate-200">
                                            <div className="w-full max-h-[600px] aspect-video bg-white flex items-center justify-center">
                                                <img
                                                    src={item.documents.acceptanceImage}
                                                    alt={item.documents.acceptanceTitle}
                                                    className="w-full h-full object-contain hover:scale-105 transition duration-500 my-3"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* Summary */}
                                <div className="p-8 border-t border-slate-200 bg-white">
                                    <h4 className="font-bold text-primary-black-500 mb-3">
                                        {item.summaryTitle}
                                    </h4>

                                    <p className="text-gray-600 leading-relaxed">
                                        {item.summary}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}